B.cr=new A.d5("nausea","Nausea","\u063a\u062b\u064a\u0627\u0646","\ud83c\udf0a",!1,4,null,"Small frequent meals every 2\u20133 hours. Cold or room-temperature foods are easier to tolerate.",!1,"Does nausea affect eating or drinking?")
B.bc=new A.d5("fatigue","Fatigue","\u0625\u0631\u0647\u0627\u0642","\ud83c\udf19",!1,4,null,"Rest when your body asks. Short 20-minute rests are better than long naps.",!1,"Does fatigue stop normal activities?")
B.cs=new A.d5("mouth_sores","Mouth sores","\u062a\u0642\u0631\u062d\u0627\u062a \u0627\u0644\u0641\u0645","\ud83d\udc44",!0,6,"Severe mouth sores can make it hard to eat or drink. Contact your team if you cannot swallow.","Rinse with salt water 4\u20136 times daily. Avoid spicy, acidic, or rough-textured foods.",!1,"Do mouth sores affect eating or speaking?")
B.jc=new A.d5("fluid_retention","Fluid retention","\u0627\u062d\u062a\u0628\u0627\u0633 \u0627\u0644\u0633\u0648\u0627\u0626\u0644","\u2696\ufe0f",!1,4,null,"Weigh yourself daily at the same time. Report a gain of 2kg+ in 48 hours.",!1,"Have you gained more than 1kg since yesterday?")
B.cO=new A.d5("breathlessness","Breathlessness","\u0636\u064a\u0642 \u0627\u0644\u062a\u0646\u0641\u0633","\ud83e\udec1",!0,4,"Breathlessness at rest or with light activity \u2014 contact your care team today.",null,!1,null)
B.hg=new A.d5("hair_loss","Hair loss","\u062a\u0633\u0627\u0642\u0637 \u0627\u0644\u0634\u0639\u0631","\ud83d\udc87",!1,4,null,"This is temporary. Gentle shampoo and a soft pillow cover can reduce scalp discomfort.",!1,"Is hair loss affecting your confidence or comfort?")
B.Ax=new A.d5("vomiting","Vomiting","\u0642\u064a\u0621","\ud83e\udd22",!0,5,"More than 2\u20133 episodes \u2014 contact your care team. You may need anti-nausea medication adjustment.","Take your anti-nausea medication as prescribed. Small sips of clear fluids help prevent dehydration.",!1,"How many episodes today?")
B.df=new A.d5("infection","Signs of infection","\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u0639\u062f\u0648\u0649","\ud83d\udd34",!0,2,"Redness, swelling, warmth around any wound or IV site \u2014 contact your team today.",null,!1,null)
B.RD=new A.d5("swelling","Swelling / fluid","\u062a\u0648\u0631\u0645","\ud83d\udca7",!1,4,null,"Elevate legs when resting. Avoid tight shoes. Report significant swelling.",!1,"Does swelling affect walking or wearing shoes?")
B.aU=new A.d5("fever","Fever / Temperature","\u062d\u0645\u0649 / \u062d\u0631\u0627\u0631\u0629","\ud83c\udf21\ufe0f",!0,3,"Fever above 38\xb0C (100.4\xb0F) during chemotherapy \u2014 call your care team immediately, day or night. Do not wait.",null,!1,null)
B.Ay=new A.d5("diarrhea","Diarrhoea","\u0625\u0633\u0647\u0627\u0644","\ud83d\udca7",!0,6,"More than 4\u20136 loose stools per day \u2014 contact your team. Risk of dehydration.",null,!1,"How many episodes today?")
B.RE=new A.d5("palpitations","Heart palpitations","\u062e\u0641\u0642\u0627\u0646 \u0627\u0644\u0642\u0644\u0628","\u2764\ufe0f",!0,3,"Irregular heartbeat or chest discomfort \u2014 contact your care team immediately.",null,!1,null)
B.mw=new A.d5("skin_nails","Skin / nail changes","\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u0644\u062f \u0648\u0627\u0644\u0623\u0638\u0627\u0641\u0631","\ud83d\udc85",!1,4,null,"Keep nails clean and short. Moisturise hands daily. Avoid cutting cuticles.",!1,"Are skin or nail changes causing discomfort?")
